pfUI.octoNotes = {
  { "1.2.86", {
    { "No more red \"Unknown addon chat type\" lines", "since 1.2.80 pfUI Octo sent its shared data to the realm's data bot as an add-on whisper, and this server refuses those - one red line every few seconds. Sending to the bot is paused (guild and raid sharing carry on as before), and if the server ever refuses one of pfUI's messages again, the line is hidden and pfUI stops trying for that session." },
  } },
  { "1.2.85", {
    { "OctoLoot scroll bars", "the instance, boss and loot lists show a thin bar on the right when there is more to scroll. Drag it or click it to jump." },
    { "Enchant tooltips in OctoLoot", "hovering an enchant recipe shows what the enchant does, as an enchant link does, above the skill levels and reagents." },
  } },
  { "1.2.84", {
    { "Heartbeat to the realm data bot", "with the zone ping every few minutes, pfUI Octo tells your realm's data bot your zone, level, class, latency, pfUI Octo version and whether you are AFK, DND, queued for a battleground or in an instance. It goes to the bot only, never to guild or raid, is held in combat like all sharing, and switches off with \"Battlegrounds, population, deaths & records\" on the Data sharing page. pfUI only reports; it never takes commands." },
  } },
  { "1.2.83", {
    { "Realm data bots are fixed", "pfUI Octo now picks the data bot by realm and faction (Y'Shaarj Horde = Errorgchat, Y'Shaarj Alliance = Octopfui, N'Zoth = Pfuiocto), and nothing can change it. The \"Master character\" box and the bot on/off switch are gone; the Data sharing page shows your realm's bot. To share nothing, turn the feeds off." },
  } },
  { "1.2.82", {
    { "N'Zoth data bot", "players on N'Zoth, Horde and Alliance alike, now share with the realm's data bot, Pfuiocto. It is invisible and has the same off switch on the Data sharing page." },
  } },
  { "1.2.81", {
    { "Y'Shaarj Alliance data bot", "Alliance players on Y'Shaarj now share with their own faction's data bot, Octopfui, the same way Horde players share with Errorgchat. It is invisible and has the same off switch on the Data sharing page." },
  } },
  { "1.2.80", {
    { "Realm-wide boards through the realm's data bot", "the feeds you already share with your guild (prices, flights, nodes, world buffs, boards, BG queues...) now also go to your realm's OctoWoW data bot as an invisible addon whisper - no chat line, no reply - so the realm-wide boards and Discord stats get everyone, not just one guild. Only your own faction's bot. If the bot is offline, the \"No player named\" line is hidden and pfUI waits 10 minutes before trying again. Off with one switch: Quality of Life > Data sharing > \"Share with the realm's data bot\"." },
  } },
  { "1.2.79", {
    { "OctoLoot trash drops (thanks Lobo)", "every dungeon and raid with trash loot now has a \"Trash mobs\" entry - Dragonmaw Retreat shows the Dragonmaw Bulwark and the Dragonmaw set pieces." },
    { "Nameplate combat text (thanks tuki)", "the combat text pages now say plainly when nampower is missing - your hits come from it, so without it only Test shows." },
    { "pfQuest missing its database", "instead of an error to report, pfUI says the files are missing and to reinstall pfUI." },
    { "Data sharing: deaths and crit records", "with \"Send new feeds\" on, pfUI also shares where you died, your level and what hit you last, and a new personal best crit or crit heal (amount and spell) - for death and record boards. Paced and silent in combat like every feed; listed on the Data sharing page, and off with that one switch." },
  } },
  { "1.2.78", {
    { "Shorter tooltips, your way", "every extra tooltip part now has its own switch on one card (Quality of Life > Tooltips > Tooltip extras). Mob hits, armor and resists each on their own (resists off, armor kept), how many creatures \"Drops from\" lists, and OctoLoot's Swaps, pages and the long \"Used in\" line - each Always, only while Shift is held, or Never. The auction price is there too." },
  } },
  { "1.2.77", {
    { "System messages can be turned back on", "logins, logouts, rolls and /played vanished from chat for some, and the game's own menu has no switch for them. Right-click a chat tab > Filters > System Messages now starts with a Show system messages tick box, and the Chat page has a System switch for the main chat." },
    { "Chat settings are back in the new chat bar", "right-click General for the game's own window menu (font size, filters, channels, colours, lock, rename). Left-click it to pick a chat window (General, Combat Log); Whispers has its own button." },
  } },
  { "1.2.76", {
    { "Fixes the \"Unknown addon chat type\" errors", "from 1.2.74/75: this client doesn't carry addon messages over a custom channel, so that's gone. Sharing is back to guild and raid, which work cleanly, with no error spam." },
    { "Realm-wide, the right way", "set your collector's name as the \"Master character\" on the Data sharing page and every client quietly whispers it (invisible) - off by default until you set it." },
  } },
  { "1.2.75", {
    { "Battleground queue times", "pfUI Octo now shares how long your BG queues take and who won, so the boards can show which brackets pop fast and how each realm is doing. Opt out on the Data sharing page." },
    { "Where is everyone", "a tiny, occasional note of your zone (never in combat) feeds an activity heatmap. No names, just a head count." },
    { "All of it rides the same throttle-safe, combat-silent sharing from ...", "All of it rides the same throttle-safe, combat-silent sharing from 1.2.74 - you won't notice it." },
  } },
  { "1.2.74", {
    { "Data sharing, one honest place", "a new Data sharing page (Quality of Life) lists everything pfUI Octo shares with other players - prices, flight and transport times, gathering nodes, world buffs, board counts - each with its own switch, and you can turn the lot off. Nothing hidden, nothing personal." },
    { "Never spams the server", "every share message is now paced onto one slow stream, so all the feeds together can never trip the chat throttle. It goes completely silent while you are in combat and backs off if the server ever complains. You will not notice it." },
    { "Realm-wide, not just your guild", "the feeds now reach the whole realm over a hidden channel that joins quietly and stays out of your chat windows, so the shared prices and timers are fuller for everyone." },
  } },
  { "1.2.73", {
    { "Fastest clears for every realm", "each realm's tab now shows its own fastest clear of each raid. Before, a realm only showed a raid when it held the record for all realms, so C'Thun and Y'Shaarj were empty." },
    { "Clear times to the second", "times are exact now, and every clear under an hour reads m:ss (a 9 minute Onyxia showed as \"9m\")." },
  } },
  { "1.2.72", {
    { "Onyxia / Nefarian buff no longer hidden", "\"Hide the tracking buff\" hid the dragon head buff along with Track Dragonkin (same icon). Only the tracking buff goes now." },
    { "Buff and debuff direction", "buffs, debuffs and weapon buffs can grow to the left or to the right, and new rows can go down or up (Buffs > Buffs and debuffs)." },
    { "Consolidated buffs, like WotLK", "long buffs (raid buffs, world buffs, food) go into one icon with a count. Hover it to see them, click to keep the box open, right-click a buff to cancel it. They come back out when they run low. Off as it comes: Buffs > Consolidated." },
    { "Map ping on you, in the right place", "the pulse when you open the map now sits right on your arrow at any map size and zoom." },
    { "Quest dots stay the right size", "taking a quest while the map was zoomed in made the dots tiny." },
    { "Fullscreen map", "a Fullscreen button next to the map's close button fills the screen (and back). It stays that way between openings." },
  } },
  { "1.2.71", {
    { "OctoBoards' realm boards count raids only", "Guild of the week, Unfinished business, Biggest turnout, Longest raid, Night owls and Realm wars no longer count dungeon runs (BRS, BRD, Black Morass...)." },
    { "Real raid lengths", "a raid now lasts from its first boss pull to its last boss kill. A log left running for days showed Blackrock Spire at 72 hours." },
    { "A raid uploaded twice counts once,", "even when the two uploads start a few seconds apart. Boards rebuilt with the latest uploads." },
  } },
  { "1.2.70", {
    { "Translations, second round", "about 19,500 new texts in German, Spanish, French, Korean, Russian and both Chinese - OctoBoards, the auction and mail windows, OctoLoot, meter breakdowns, the minigames, OctoRinse and CooldownManager options, layout mode and the first-run setup." },
    { "Translated everywhere", "pfUI Octo's own windows, buttons and tooltips now use the translations too, not only the options pages." },
